const LABEL = "A.J. Marksberry, Senior Product Designer, with a fishing habit";

/** The shapes, drawn nowhere themselves: both layouts reference them. */
function Sprite() {
  return (
    <svg
      width="0"
      height="0"
      aria-hidden
      focusable="false"
      className="absolute"
    >
      <defs>
        <path
          id="hero-def-name"
          fillRule="evenodd"
          clipRule="evenodd"
          d={NAME}
        />
        <path id="hero-def-title" d={TITLE} />
        <clipPath id="hero-clip-b">
          <rect x="907.2" y="240" width="40" height="60" />
        </clipPath>
        <g id="hero-def-tagline" fillRule="evenodd" clipRule="evenodd">
          <path d={TAGLINE_FRONT} />
          <path d={HABIT_H} transform="translate(134.4 0)" />
          <path d={HABIT_A} transform="translate(126.5 0)" />
          <g transform="translate(-9.8 0)">
            <path d={HABIT_B} clipPath="url(#hero-clip-b)" />
          </g>
          <path d={HABIT_IT} transform="translate(197.9 0)" />
        </g>
        <path
          id="hero-def-fish"
          fillRule="evenodd"
          clipRule="evenodd"
          d={FISH}
        />
        <path id="hero-def-fish-body" d={FISH_BODY} />
        <path id="hero-def-fish-fin" d={FISH_FIN} />
        <path
          id="hero-def-wave-2"
          fillRule="evenodd"
          clipRule="evenodd"
          d={WAVE_2}
        />
        <path id="hero-def-wave-3-fill" d={WAVE_3_FILL} />
        <clipPath id="hero-clip-wave-3-keep">
          <rect x="439.4" y="0" width="461.2" height="2000" />
        </clipPath>
        <clipPath id="hero-clip-wave-3-tile">
          <rect x="599.4" y="0" width="161.2" height="2000" />
        </clipPath>
        <path
          id="hero-def-wave-3"
          fillRule="evenodd"
          clipRule="evenodd"
          d={WAVE_3}
        />
      </defs>
    </svg>
  );
}

/* Each piece keeps its animation class on its own group. A layout that moves or
 * scales a piece does it on a group OUTSIDE this one: a CSS animation's
 * transform would replace a transform set on the same element. */
function Name() {
  return (
    <g className="hero-art-name">
      <use href="#hero-def-name" className="fill-heading" />
    </g>
  );
}

function Title() {
  return (
    <g className="hero-art-title">
      <use href="#hero-def-title" className="fill-[#FF5A5F]" />
    </g>
  );
}

function Tagline({ shift }: { shift: number }) {
  return (
    <g className="hero-art-tagline">
      <g transform={`translate(${shift} 0)`}>
        <use href="#hero-def-tagline" className="fill-heading" />
      </g>
    </g>
  );
}

/* The front wave runs the full width of the page, whatever the screen. The
 * drawing is 1,180 units wide; the part of it from x 440 to 900 (four crests)
 * is kept as drawn, and out from both ends of that, one period of it (x 600 to
 * 760, one crest and one valley) is repeated, each copy nudged up or down so its
 * line meets the last. Draws one piece of the wave (its line, or the fill under
 * it), so the same run can be made for each of them. */
const WAVE_TILES = 14;
/* How far the front wave is moved down from where it was drawn (units). */
const WAVE_3_DROP = 8;
function WaveRun({
  href,
  className,
  fill,
}: {
  href: string;
  className?: string;
  fill?: string;
}) {
  const use = <use href={href} className={className} fill={fill} />;
  const tile = (key: string, dx: number, dy: number) => (
    <g key={key} transform={`translate(${dx} ${dy})`}>
      <g clipPath="url(#hero-clip-wave-3-tile)">{use}</g>
    </g>
  );
  const tiles = [];
  for (let k = 0; k < WAVE_TILES; k++) {
    tiles.push(tile(`r${k}`, 300 + 160 * k, -3.5 + 2.5 * k));
    tiles.push(tile(`l${k}`, -320 - 160 * k, 4 + 2.5 * k));
  }
  /* One wrapper: the waves' bob animation moves each direct child of
   * .hero-wave, and would replace the tiles' own transforms. */
  return (
    <g>
      <g transform={`translate(0 ${WAVE_3_DROP})`}>
        <g clipPath="url(#hero-clip-wave-3-keep)">{use}</g>
        {tiles}
      </g>
    </g>
  );
}

/** The fish standing in the waves. Waves first, so the fish is in front. */
